#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <ctype.h>

#define MAX_SESSIONS 64
#define TOKEN_LEN 32
#define HEADER_MAGIC 0x41555448

/* Session permission levels */
#define PERM_NONE    0
#define PERM_READ    1
#define PERM_WRITE   2
#define PERM_ADMIN   3

typedef struct {
    uint32_t magic;
    int16_t  msg_type;    /* 1=login, 2=query, 3=setperm */
    int16_t  payload_len;
} __attribute__((packed)) msg_header_t;

typedef struct {
    char     username[32];
    char     token[TOKEN_LEN];
    uint8_t  permission;
    uint8_t  active;
    uint16_t session_id;
} session_entry_t;

static session_entry_t g_sessions[MAX_SESSIONS];
static int g_session_count = 0;

/* Lookup table for permission escalation thresholds */
static const int g_perm_thresholds[4] = {0, 10, 50, 100};

/*
 * find_session_index - locate session by ID
 * Returns index into g_sessions array, or -1 if not found.
 * NOTE: session_id is provided by client in the protocol header.
 */
static int find_session_index(int session_id) {
    int i;
    for (i = 0; i < g_session_count; i++) {
        if (g_sessions[i].active && g_sessions[i].session_id == (uint16_t)session_id) {
            return i;
        }
    }
    return -1;
}

/*
 * validate_permission_update - checks if the requested permission
 * level change is within bounds for the given session slot.
 *
 * slot_index: index into g_sessions (validated by caller)
 * requested_level: new permission level from client
 *
 * Returns 1 if valid, 0 if denied.
 */
static int validate_permission_update(int slot_index, int requested_level) {
    /* Ensure slot_index is within valid range */
    if (slot_index < 0 || slot_index >= g_session_count) {
        return 0;
    }
    /* Ensure requested level is within defined permission range */
    if (requested_level < PERM_NONE || requested_level > PERM_ADMIN) {
        return 0;
    }
    /* Only allow escalation one step at a time */
    int current = g_sessions[slot_index].permission;
    if (requested_level > current + 1) {
        return 0;
    }
    return 1;
}

/*
 * apply_permission_change - applies a validated permission change.
 * Directly indexes the session array with bounds checking.
 */
static void apply_permission_change(unsigned int session_index, uint8_t new_perm) {
    if (session_index >= MAX_SESSIONS) return;
    g_sessions[session_index].permission = new_perm;
}

/*
 * compute_target_index - calculate the target session index
 * from a base index and relative offset.
 *
 * Uses unsigned arithmetic to prevent negative index attacks.
 * Returns the validated target index, or -1 on error.
 */
static int compute_target_index(int base_index, int relative_index) {
    int target_index = base_index + relative_index;
    /* Bounds check: target must be within valid session range */
    if (target_index < 0 || target_index >= g_session_count) {
        return -1;
    }
    if (target_index >= MAX_SESSIONS) {
        return -1;
    }
    return target_index;
}

static int handle_login(int client_fd, const char *payload, int len) {
    if (len < 33) return -1; /* need username + at least 1 byte token */
    if (g_session_count >= MAX_SESSIONS) return -1;

    int idx = g_session_count;
    memset(&g_sessions[idx], 0, sizeof(session_entry_t));
    strncpy(g_sessions[idx].username, payload, 31);
    g_sessions[idx].username[31] = '\0';
    memcpy(g_sessions[idx].token, payload + 32, TOKEN_LEN > (len-32) ? (len-32) : TOKEN_LEN);
    g_sessions[idx].permission = PERM_NONE;
    g_sessions[idx].active = 1;
    g_sessions[idx].session_id = (uint16_t)(idx + 1);
    g_session_count++;

    char resp[64];
    snprintf(resp, sizeof(resp), "OK SESSION %u\n", g_sessions[idx].session_id);
    write(client_fd, resp, strlen(resp));
    return 0;
}

static int handle_setperm(int client_fd, const char *payload, int len) {
    if (len < 4) return -1;

    /* Parse: [2 bytes session_id] [1 byte relative_offset] [1 byte new_perm] */
    uint16_t target_session = *(uint16_t *)payload;
    int8_t relative_offset = (int8_t)payload[2];  /* signed relative index */
    uint8_t new_perm = (uint8_t)payload[3];

    /* Find the requesting session */
    int base_idx = find_session_index(target_session);
    if (base_idx < 0) {
        write(client_fd, "ERR NO_SESSION\n", 15);
        return -1;
    }

    /* Compute and validate target index */
    int target_idx = compute_target_index(base_idx, (int)relative_offset);
    if (target_idx < 0) {
        write(client_fd, "ERR OUT_OF_BOUNDS\n", 18);
        return -1;
    }

    /* Validate the permission level */
    if (!validate_permission_update(target_idx, (int)new_perm)) {
        write(client_fd, "ERR DENIED\n", 11);
        return -1;
    }

    /* Apply the change with bounds-checked index */
    apply_permission_change((unsigned int)target_idx, new_perm);
    write(client_fd, "OK PERM_UPDATED\n", 16);
    return 0;
}

static int handle_query(int client_fd, const char *payload, int len) {
    if (len < 2) return -1;
    uint16_t session_id = *(uint16_t *)payload;
    int idx = find_session_index(session_id);
    if (idx < 0) {
        write(client_fd, "ERR NO_SESSION\n", 15);
        return -1;
    }
    char resp[128];
    snprintf(resp, sizeof(resp), "SESSION %u USER=%s PERM=%d\n",
             g_sessions[idx].session_id, g_sessions[idx].username,
             g_sessions[idx].permission);
    write(client_fd, resp, strlen(resp));
    return 0;
}

static void process_client(int client_fd) {
    char buf[512];
    ssize_t n;

    while ((n = read(client_fd, buf, sizeof(buf))) > 0) {
        if ((size_t)n < sizeof(msg_header_t)) continue;

        msg_header_t *hdr = (msg_header_t *)buf;
        if (hdr->magic != HEADER_MAGIC) continue;
        if (hdr->payload_len < 0 || hdr->payload_len > (int)(n - sizeof(msg_header_t))) continue;

        char *payload = buf + sizeof(msg_header_t);

        switch (hdr->msg_type) {
            case 1: handle_login(client_fd, payload, hdr->payload_len); break;
            case 2: handle_query(client_fd, payload, hdr->payload_len); break;
            case 3: handle_setperm(client_fd, payload, hdr->payload_len); break;
            default: write(client_fd, "ERR UNKNOWN\n", 12); break;
        }
    }
}

int main(int argc, char *argv[]) {
    int port = 9100;
    if (argc > 1) port = atoi(argv[1]);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); return 1;
    }
    listen(server_fd, 5);
    printf("Auth service on port %d\n", port);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) continue;
        process_client(client_fd);
        close(client_fd);
    }
    return 0;
}
